    "short": "비엠티는 산업용 배관과 전력설비 부품을 만드는 회사",
    "summary": "비엠티는 산업용 배관과 전력설비 부품을 만드는 회사입니다. 배관을 연결하는 피팅과 흐름을 조절하는 밸브를 공급합니다.",
    "takeaways": [
      "비엠티는 산업용 배관과 전력설비 부품을 만드는 회사입니다.",
      "배관을 연결하는 피팅과 흐름을 조절하는 밸브를 공급합니다.",
      "반도체·조선·발전·석유가스 설비 등에 제품이 쓰입니다.",
      "배전반과 전력 감시·제어 시스템도 제조합니다.",
      "산업시설 투자와 제품 규격, 금속 원가를 함께 봅니다."
    ],
    "business": [
      {
        "name": "피팅·밸브",
        "desc": "산업 배관 연결·유량 제어용 정밀 부품을 만듭니다."
      },
      {
        "name": "모듈·시스템",
        "desc": "공정 조건에 맞춘 배관 모듈 등을 공급합니다."
      },
      {
        "name": "전력설비",
        "desc": "분전반·배전반과 전력 감시 시스템을 제조합니다."
      }
    ],
    "drivers": [
      {
        "title": "산업 투자",
        "desc": "반도체·조선·플랜트 발주가 제품 수요에 영향을 줍니다."
      },
      {
        "title": "품질·규격",
        "desc": "압력·누설 등 고객 요구와 인증 충족이 중요합니다."
      },
      {
        "title": "원가·수출",
        "desc": "금속·정밀 가공 비용과 해외 판매 조건을 확인합니다."
      }
